    return () => { editor.off('change', onChange); };
  }, [editor]);
  const html = useMemo(() => markdownParser.render(markdown), [markdown]);
  const words = markdown.trim().split(/\\s+/u).filter(Boolean).length;
  const titleError = attempted && "'!title.trim();
