  .main { padding-right: var(--g-spacing-6); padding-left: var(--g-spacing-6); }
  .header-inner { padding: 0 var(--g-spacing-6); }
  .preview-content { padding-right: var(--g-spacing-5); padding-left: var(--g-spacing-5); }
  .form-footer { align-items: flex-start; flex-direction: column-reverse; }
  .form-actions { align-self: flex-end; }
  .live-badge { display: none "'!important; }
}
@media (max-width: 700px) {
  .app-header { height: 64px; }
  .header-inner { padding: 0 var(--g-spacing-4); gap: var(--g-spacing-3); }
  .workspace-name, .header-divider, .help-label { display: none; }
  .header-actions { gap: var(--g-spacing-3); }
  .main { padding: var(--g-spacing-5) var(--g-spacing-4); }
  .breadcrumbs { margin-bottom: var(--g-spacing-6); }
  .page-heading { align-items: flex-start; margin-bottom: var(--g-spacing-5); gap: var(--g-spacing-2); }
  .eyebrow { font-size: 8px; letter-spacing: 1px; }
  .page-title { font-size: var(--g-text-header-2-font-size); line-height: var(--g-text-header-2-line-height); }
  .page-description { font-size: 12px; line-height: 20px; }
  .draft-badge { margin-top: var(--g-spacing-6); font-size: 10px; padding: var(--g-spacing-1) var(--g-spacing-2); }
  .form-details, .content-section { padding: var(--g-spacing-4); }
  .section-caption { display: none; }
  .details-grid { grid-template-columns: minmax(0, 1fr); gap: var(--g-spacing-4); }
  .content-heading { align-items: flex-start; flex-direction: column; }
  .editor-topbar { padding: var(--g-spacing-2); }
  .editor-tip { display: none; }
  .editor-columns { grid-template-columns: minmax(0, 1fr); }
  .source-pane { border-right: 0; border-bottom: 1px solid var(--g-color-line-generic); min-height: 300px; max-height: 400px; }
  .preview-content { max-height: none; padding: var(--g-spacing-2) var(--g-spacing-4) var(--g-spacing-5); }
  .preview-heading .live-badge { display: flex !important; }
  .editor-status { flex-wrap: wrap; }
  .writing-note { padding: var(--g-spacing-3); }
  .form-footer { padding: var(--g-spacing-4); }
  .form-actions { flex-direction: column; width: 100%; }
  .page-footer { align-items: flex-start; gap: var(--g-spacing-2); font-size: 10px; }
  .page-footer > span { max-width: 60%; line-height: 18px; }
}
EOF'
